const express = require('express');
const cors = require('cors');
const fs = require('fs');
const path = require('path');
const { initTRPC } = require('@trpc/server');
const { createExpressMiddleware } = require('@trpc/server/adapters/express');

const LOG_PATH = '/home/user/project/output.log';

const logLine = (message) => {
  const line = `[server] ${new Date().toISOString()} ${message}`;
  fs.appendFileSync(LOG_PATH, `${line}\n`);
  console.log(line);
};

const t = initTRPC.create();

const appRouter = t.router({
  countdown: t.procedure.subscription(async function* () {
    for (let count = 5; count >= 1; count -= 1) {
      yield count;
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
  }),
});

const app = express();
app.use(cors());
app.use(
  '/trpc',
  createExpressMiddleware({
    router: appRouter,
  }),
);

const port = 3000;
app.listen(port, () => {
  logLine(`tRPC SSE server listening on http://localhost:${port}/trpc`);
});

module.exports = { appRouter };

const fs = require('fs');
const { createTRPCProxyClient, httpSubscriptionLink } = require('@trpc/client');

const LOG_PATH = '/home/user/project/output.log';
const OUTPUT_PATH = '/home/user/project/output.json';

const logLine = (message) => {
  const line = `[client] ${new Date().toISOString()} ${message}`;
  fs.appendFileSync(LOG_PATH, `${line}\n`);
  console.log(line);
};

const client = createTRPCProxyClient({
  links: [
    httpSubscriptionLink({
      url: 'http://localhost:3000/trpc',
      EventSource: require('eventsource'),
    }),
  ],
});

const run = async () => {
  const values = [];

  await new Promise((resolve, reject) => {
    const subscription = client.countdown.subscribe(undefined, {
      onData(data) {
        values.push(data);
        logLine(`received ${data}`);
      },
      onError(error) {
        logLine(`subscription error: ${error?.message || error}`);
        subscription?.unsubscribe();
        reject(error);
      },
      onComplete() {
        logLine('subscription complete');
        resolve();
      },
    });
  });

  fs.writeFileSync(OUTPUT_PATH, JSON.stringify(values));
  logLine(`wrote ${values.length} values to ${OUTPUT_PATH}`);
};

run()
  .then(() => process.exit(0))
  .catch(() => process.exit(1));

